using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;using Microsoft.EntityFrameworkCore;using RaceDay.Api.Data;using RaceDay.Api.DTOs;using RaceDay.Api.Models;
namespace RaceDay.Api.Controllers;
[ApiController,Route("api/events/{eventId:int}/categories")]
public class EventCategoriesController(RaceDayContext db):ControllerBase{
 [HttpGet,AllowAnonymous,ProducesResponseType(typeof(IEnumerable<OfferingResponse>),200)] public async Task<IActionResult> All(int eventId){if(!await db.Events.AnyAsync(x=>x.EventID==eventId))return NotFound();return Ok(await db.EventCategories.Where(x=>x.EventID==eventId).Select(x=>new OfferingResponse(x.EventID,x.CategoryID,x.Event!.EventName,x.Category!.CategoryName,x.Category.DistanceKm,x.EntryFee,x.Capacity,x.Enrolments.Count(y=>y.Status=="Confirmed"))).ToListAsync());}
 [HttpPost,Authorize(Roles="Organiser"),ProducesResponseType(typeof(OfferingResponse),201)] public async Task<IActionResult> Add(int eventId,[FromQuery]int categoryId,OfferingRequest r){if(!await db.Events.AnyAsync(x=>x.EventID==eventId))return NotFound(new{message="Event not found."});if(!await db.Categories.AnyAsync(x=>x.CategoryID==categoryId))return NotFound(new{message="Category not found."});if(await db.EventCategories.AnyAsync(x=>x.EventID==eventId&&x.CategoryID==categoryId))return Conflict(new{message="Category is already offered for this event."});var ec=new EventCategory{EventID=eventId,CategoryID=categoryId,EntryFee=r.EntryFee,Capacity=r.Capacity};db.EventCategories.Add(ec);await db.SaveChangesAsync();var result=await db.EventCategories.Where(x=>x.EventID==eventId&&x.CategoryID==categoryId).Select(x=>new OfferingResponse(x.EventID,x.CategoryID,x.Event!.EventName,x.Category!.CategoryName,x.Category.DistanceKm,x.EntryFee,x.Capacity,0)).SingleAsync();return CreatedAtAction(nameof(All),new{eventId},result);}
 [HttpPut("{categoryId:int}"),Authorize(Roles="Organiser"),ProducesResponseType(typeof(OfferingResponse),200),ProducesResponseType(404)] public async Task<IActionResult> Update(int eventId,int categoryId,OfferingRequest r){var ec=await db.EventCategories.Include(x=>x.Event).Include(x=>x.Category).Include(x=>x.Enrolments).SingleOrDefaultAsync(x=>x.EventID==eventId&&x.CategoryID==categoryId);if(ec is null)return NotFound();if(r.Capacity<ec.Enrolments.Count(x=>x.Status=="Confirmed"))return BadRequest(new{message="Capacity cannot be lower than confirmed enrolments."});ec.EntryFee=r.EntryFee;ec.Capacity=r.Capacity;await db.SaveChangesAsync();return Ok(new OfferingResponse(eventId,categoryId,ec.Event!.EventName,ec.Category!.CategoryName,ec.Category.DistanceKm,ec.EntryFee,ec.Capacity,ec.Enrolments.Count(x=>x.Status=="Confirmed")));}
 [HttpDelete("{categoryId:int}"),Authorize(Roles="Organiser"),ProducesResponseType(204),ProducesResponseType(404)] public async Task<IActionResult> Remove(int eventId,int categoryId){var ec=await db.EventCategories.Include(x=>x.Enrolments).SingleOrDefaultAsync(x=>x.EventID==eventId&&x.CategoryID==categoryId);if(ec is null)return NotFound();if(ec.Enrolments.Count>0)return Conflict(new{message="Cannot remove an offering that already has enrolments."});db.EventCategories.Remove(ec);await db.SaveChangesAsync();return NoContent();}
}
